{
  "root": "mainStack",
  "state": {},
  "elements": {
    "mainStack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "titleText",
        "descriptionText",
        "tableCard"
      ]
    },
    "titleText": {
      "type": "Text",
      "props": {
        "text": "US City Population Snapshot",
        "variant": "h2"
      },
      "children": []
    },
    "descriptionText": {
      "type": "Text",
      "props": {
        "text": "This table visualizes the population of major US cities, ranked from highest to lowest.",
        "variant": "body"
      },
      "children": []
    },
    "tableCard": {
      "type": "Card",
      "props": {},
      "children": [
        "tableTitle",
        "populationTable",
        "tableDivider",
        "viewMoreButton"
      ]
    },
    "tableTitle": {
      "type": "Text",
      "props": {
        "text": "Major US City Populations",
        "variant": "h3"
      },
      "children": []
    },
    "populationTable": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "City",
            "label": "City"
          },
          {
            "key": "Population",
            "label": "Population"
          }
        ],
        "rows": [
          {
            "City": "New York",
            "Population": 8400000
          },
          {
            "City": "Los Angeles",
            "Population": 3900000
          },
          {
            "City": "Chicago",
            "Population": 2700000
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "primaryColumn": "City",
        "highlightColumns": [
          "Population"
        ],
        "numericColumns": [
          "Population"
        ]
      },
      "children": []
    },
    "tableDivider": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "viewMoreButton": {
      "type": "Button",
      "props": {
        "label": "View More Data"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/city-data"
          }
        }
      }
    }
  }
}
